try {
// 超时时间 6s
let controller = new AbortController();
setTimeout(() => {
controller.abort();
}, 6000);
let res = await fetch("https://baidu.com/", {
mode: "no-cors",
// ↑ 这种模式 (opaque mode) 不可以获取到任何响应数据和请求头，但如果出现响应异常，依然会有错误抛出。通过这个来检查是否成功访问了目标地址
signal: controller.signal
});
// 接着是有正常响应的情况
} catch (e) {
// 失败情况 (超时或网络错误)
}
